solution.javascript:
function minWindow(s, t) {
  const need = {}; for (const c of t) need[c] = (need[c] || 0) + 1;
  let have = 0, needCount = Object.keys(need).length;
  const window = {};
  let bestStart = 0, bestLen = Infinity, left = 0;
  for (let right = 0; right < s.length; right++) {
    window[s[right]] = (window[s[right]] || 0) + 1;
    if (need[s[right]] && window[s[right]] === need[s[right]]) have++;
    while (have === needCount) {
      if (right - left + 1 < bestLen) { bestLen = right - left + 1; bestStart = left; }
      window[s[left]]--;
      if (need[s[left]] && window[s[left]] < need[s[left]]) have--;
      left++;
    }
  }
  return bestLen === Infinity ? '' : s.slice(bestStart, bestStart + bestLen);
}

solution.cpp:
string minWindow(string s, string t) {
    unordered_map<char, int> need;
    for (char c : t) need[c]++;
    int have = 0, needCount = need.size();
    unordered_map<char, int> window;
    int bestStart = 0, bestLen = INT_MAX, left = 0;
    for (int right = 0; right < s.size(); right++) {
        window[s[right]]++;
        if (need.count(s[right]) && window[s[right]] == need[s[right]]) have++;
        while (have == needCount) {
            if (right - left + 1 < bestLen) { bestLen = right - left + 1; bestStart = left; }
            window[s[left]]--;
            if (need.count(s[left]) && window[s[left]] < need[s[left]]) have--;
            left++;
        }
    }
    return bestLen == INT_MAX ? "" : s.substr(bestStart, bestLen);
}
